//
//  OpusPlayoutTests.swift
//  OSHITests
//
//  __CALL_FLUIDITY_2026_11_21__ The 0x19 receive path through `AdaptiveJitterBuffer` +
//  `OpusPlayoutDecoder`: reordering, in-band FEC, and wire compatibility. The first four are
//  ports of the Kotlin `OpusPlayoutTest` (desktop + Android); the rest are iOS-specific:
//  the desktop's golden payloads (Concentus, the stream every desktop/Android peer sends)
//  decoded here, and the iOS sender's own bytes pinned to release/ios-1.0.49.
//

import XCTest
import CryptoKit
@testable import OSHI

final class OpusPlayoutTests: XCTestCase {

    private func voice(_ frames: Int) -> [Int16] {
        (0..<(frames * 960)).map { i in
            let t: Double = Double(i) / 48_000.0
            let env: Double = 0.6 + 0.4 * sin(2.0 * Double.pi * 3.0 * t)
            let car: Double = sin(2.0 * Double.pi * 180.0 * t) + 0.4 * sin(2.0 * Double.pi * 540.0 * t)
            return Int16(truncatingIfNeeded: Int(5000.0 * env * car))
        }
    }

    private func rms(_ a: [Int16], _ from: Int = 0, _ n: Int? = nil) -> Double {
        let n = n ?? a.count
        var s = 0.0
        for i in from..<(from + n) { s += Double(a[i]) * Double(a[i]) }
        return (s / Double(n)).squareRoot()
    }

    private static func sha(_ payloads: [Data]) -> String {
        var h = SHA256()
        for p in payloads { h.update(data: p) }
        return h.finalize().map { String(format: "%02x", $0) }.joined()
    }

    func testPacketsThatOvertookFourOthersDoNotCostTheFourRealFrames() {
        let payloads = OpusCallEncoder()!.encode(voice(40))
        // 10..14 arrive after 15..18 — still before their slots are due.
        let order = Array(0..<10) + Array(15...18) + Array(10...14) + Array(19..<40)
        var now: Int64 = 0
        let jb = AdaptiveJitterBuffer(decoder: OpusPlayoutDecoder(), clock: { now })
        let unwrap = SeqUnwrapper()
        for i in 0..<3 { OpusPlayoutDecoder.file(payloads[order[i]], into: jb, unwrap: unwrap) }
        var next = 3
        for _ in 0..<60 {
            now += 20
            if next < order.count { OpusPlayoutDecoder.file(payloads[order[next]], into: jb, unwrap: unwrap); next += 1 }
            if next < order.count && (15...17).contains(order[next - 1]) {
                OpusPlayoutDecoder.file(payloads[order[next]], into: jb, unwrap: unwrap); next += 1
            }
            _ = jb.pull()
        }
        XCTAssertEqual(jb.framesPlayed, 40, "every frame played for real")
        XCTAssertEqual(jb.framesLossConcealed, 0)

        // The decode-on-arrival chain it replaces (release/ios-1.0.49): the same order costs
        // real frames.
        let old = OpusCallDecoder()!
        var concealed = 0
        for i in order {
            let frames = old.decode(payloads[i])
            // A frame the old chain produced for a seq it had not received is PLC.
            if (15...18).contains(i) { concealed += frames.filter { $0.offset < -2 }.count }
        }
        XCTAssertGreaterThanOrEqual(concealed, 2, "old chain concealed \(concealed) real frames")
    }

    func testInBandFecRecoversALostFrameFromTheNextOneWhenTheSenderCarriesIt() {
        // No repeated copies, LBRR on: frame 20 can only come back through FEC.
        let enc = OpusCallEncoder(bitrate: 32_000, complexity: 8, redundancy: 0, inbandFecLossPct: 20)!
        let payloads = enc.encode(voice(60))
        var now: Int64 = 0
        let dec = OpusPlayoutDecoder()
        let jb = AdaptiveJitterBuffer(decoder: dec, clock: { now })
        let unwrap = SeqUnwrapper()
        var out: [(AdaptiveJitterBuffer.Kind, [Int16])] = []
        for (i, p) in payloads.enumerated() {
            if i != 20 { OpusPlayoutDecoder.file(p, into: jb, unwrap: unwrap) }
            if i >= 2 { now += 20; let f = jb.pull(); out.append((jb.kind(), f)) }
        }
        XCTAssertGreaterThanOrEqual(dec.fecDecodes, 1, "FEC decode used")
        XCTAssertEqual(jb.framesLossConcealed, 1)
        // The recovered frame is voice, not a fade to silence.
        guard let at = out.firstIndex(where: { $0.0 == .lossConceal }) else { return XCTFail("no concealed frame") }
        XCTAssertGreaterThan(at, 0)
        XCTAssertGreaterThan(rms(out[at].1), 0.3 * rms(out[at - 1].1))
    }

    func testFecTurnedOnIsStillAPlainOpusStreamForAnOldReceiver() {
        // An old build decodes with OpusCallDecoder and never asks for FEC.
        let src = voice(50)
        let withFec = OpusCallEncoder(bitrate: 32_000, complexity: 8, inbandFecLossPct: 10)!.encode(src)
        let old = OpusCallDecoder()!
        let pcm = withFec.flatMap { p in old.decode(p).flatMap { $0.pcm } }
        XCTAssertEqual(pcm.count, 50 * 960)
        XCTAssertGreaterThan(rms(pcm, 10 * 960, 30 * 960), 0.5 * rms(src, 10 * 960, 30 * 960))
    }

    /// iOS counterpart of the Kotlin golden test: SHA-256 of the first 50 payloads of
    /// `OpusCallEncoder()` (the call default, 28 kbit/s, complexity 10) for this input,
    /// computed on release/ios-1.0.49 (f4c2734b) BEFORE any change — same value from a native
    /// macOS build of that commit's OshiCodec.swift + oshi_opus_a/b.c. Equal here = the wire
    /// is unchanged: no new field, FEC off.
    func testTheDefaultSenderIsByteIdenticalToRelease1049() {
        let payloads = OpusCallEncoder()!.encode(voice(50))
        XCTAssertEqual(payloads.count, 50)
        XCTAssertEqual(Self.sha(payloads), Self.iosGolden1049)
    }

    /// The stream desktop/Android send (Concentus, `OpusCallEncoder()` there): the 50 payloads
    /// whose SHA-256 the Kotlin `OpusPlayoutTest` pins, decoded by this build. In order they must
    /// come out sample-for-sample as the 1.0.49 decoder (`OpusCallDecoder`) plays them, and with
    /// two packets lost the redundancy must still bring back every frame.
    func testDesktopAndAndroidGoldenStreamDecodesHere() throws {
        let payloads = Self.desktopGolden.map { hex -> Data in
            var d = Data(capacity: hex.count / 2)
            var it = hex.makeIterator()
            while let a = it.next(), let b = it.next() { d.append(UInt8(String([a, b]), radix: 16)!) }
            return d
        }
        XCTAssertEqual(Self.sha(payloads), Self.desktopGoldenSha, "fixture = the payloads the Kotlin test pins")

        // 1.0.49 decoder, in order.
        let old = OpusCallDecoder()!
        let legacy = payloads.flatMap { old.decode($0).map { $0.pcm } }
        XCTAssertEqual(legacy.count, 50)

        // New path, in order: identical frames.
        func play(_ indices: [Int]) -> (AdaptiveJitterBuffer, [[Int16]]) {
            var now: Int64 = 0
            let jb = AdaptiveJitterBuffer(decoder: OpusPlayoutDecoder(), clock: { now })
            let unwrap = SeqUnwrapper()
            var normal: [[Int16]] = []
            var next = 0
            for _ in 0..<80 {
                now += 20
                if next < indices.count { XCTAssertTrue(OpusPlayoutDecoder.file(payloads[indices[next]], into: jb, unwrap: unwrap)); next += 1 }
                let f = jb.pull()
                if jb.kind() == .normal { normal.append(f) }
            }
            return (jb, normal)
        }
        let (jb, normal) = play(Array(0..<50))
        XCTAssertEqual(jb.framesPlayed, 50)
        XCTAssertEqual(jb.framesLossConcealed, 0)
        XCTAssertEqual(normal, legacy, "same PCM as the 1.0.49 decoder")
        XCTAssertGreaterThan(rms(normal.flatMap { $0 }, 10 * 960, 30 * 960), 0.5 * rms(voice(50), 10 * 960, 30 * 960))

        // Packets 20 and 21 lost: 22 carries 20 and 21 (two redundant copies).
        let (jb2, normal2) = play((0..<50).filter { $0 != 20 && $0 != 21 })
        XCTAssertEqual(jb2.framesPlayed, 50)
        XCTAssertEqual(jb2.framesLossConcealed, 0)
        XCTAssertEqual(normal2.count, 50)
    }

    /// Gap 10: a payload that does not parse is named in the log, no longer dropped silently.
    func testRejectReasonNamesWhyA0x19DidNotParse() {
        let good = OpusCallEncoder()!.encode(voice(3))[2]
        XCTAssertNil(OpusWire.rejectReason(good))
        var v2 = good; v2[v2.startIndex] = (2 << 4) | (v2[v2.startIndex] & 0x0F)
        XCTAssertEqual(OpusWire.rejectReason(v2)?.hasPrefix("version=2"), true)
        XCTAssertEqual(OpusWire.rejectReason(Data([0x10, 0x00]))?.hasPrefix("short"), true)
        let truncated = Data([0x12, 0x00, 0x05, 0xFF, 0x01])   // 3 frames, first claims 255 B
        XCTAssertEqual(OpusWire.rejectReason(truncated)?.hasPrefix("malformed"), true)
    }

    /// Gap 10: `pack` never writes a length byte smaller than the frame it prefixes.
    func testPackNeverWritesALyingLengthByte() {
        let big = Data(repeating: 0xAB, count: 300), small = Data(repeating: 0xCD, count: 40), last = Data(repeating: 0xEF, count: 50)
        let p = OpusWire.pack(seq: 7, frames: [small, big, last])
        let u = try! XCTUnwrap(OpusWire.unpack(p))
        XCTAssertEqual(u.frames, [last], "the oversized redundant frame and the older one are left out")
        let q = OpusWire.pack(seq: 7, frames: [small, last])
        XCTAssertEqual(OpusWire.unpack(q)?.frames, [small, last])
    }

    static let iosGolden1049 = "525a279f09ab78b1528cf5a922fdcbed7f046f87b9c1ab5213fa73007c48e5cc"
    static let desktopGoldenSha = "f6c3c9af4b3da6d0da8a3c68123ba6ca04741fd500814f81ff9313b577815242"

